    Removes the duplicate characters from the string s such that the first appearance
    of each character is preserved, while subsequent appearances are ignored.

    Parameters:
    s (str): The input string.

    Returns:
    str: The string with duplicate characters removed.
    """
    char_map = {}
    char_index = {}

    for char, index in enumerate(s):
        if char in char_index and char_index[char] > 0:
            char_index[char] -= 1
        else:
            char_index[char] = index + 1
        char_map[char] = char_index[char] + 1

    result = []
    for char, count in char_map.items():
        if count > 1:
            continue
        result.append(char)

    return ''.join(result)
