        # Pop the current island
        while stack and grid[x][y] == '1':
            # Push all adjacent (x, y) directions to the stack
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                next_x, next_y = x + dx, y + dy
                if 0 <= next_x < len(grid) and 0 <= next_y < len(grid[0][next_y]) and grid[next_x][next_y] == '1':
                    heapq.heappush(stack, (next_x, next_y))
            # Since we use a heap, we need to handle the pop carefully in the main loop
            if not stack and not grid[x][y]:
