    """
    Returns a list of prime numbers from the input list, arranged in descending order.

    Parameters:
    numbers (list): List of integers to check for primality.

    Returns:
    list: List of prime numbers in descending order.
    """
    prime_numbers = set()

    # Iterate from the maximum element down to 2
    for number in numbers:
        if number <= 1:
            continue
        if number == 2:
            prime_numbers.add(number)
        elif number % 2 == 0:
            continue
        # Check for divisors from 3 up to the square root of the number
        else:
            for divisor in range(3, int(number**0.5) + 1):
                if number % divisor == 0:
                    break
            else:
                prime_numbers.add(number)

    # Convert set back to a list and sort in descending order
    return sorted(prime_numbers, reverse=True)
